parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "po_number": {
      "type": "string",
      "description": "Customer purchase order number referenced by the vendor, e.g. PO-45001. Empty string if absent."
    },
    "vendor_name": {
      "type": "string",
      "description": "Name of the vendor company sending the document"
    },
    "vendor_reference": {
      "type": "string",
      "description": "Vendor's own document number: invoice number, order confirmation number, or shipment number"
    },
    "document_type": {
      "type": "string",
      "enum": [
        "order_confirmation",
        "invoice",
        "shipping_notice",
        "other"
      ]
    },
    "document_date": {
      "type": "string",
      "description": "Date on the document, ISO 8601 (YYYY-MM-DD)"
    },
    "currency": {
      "type": "string",
      "description": "ISO 4217 currency code, e.g. USD"
    },
    "total_amount": {
      "type": "number",
      "description": "Document total as a plain number, no thousands separators"
    },
    "line_items": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "line_no": {
            "type": "integer"
          },
          "sku": {
            "type": "string",
            "description": "Item or part number exactly as printed"
          },
          "description": {
            "type": "string"
          },
          "quantity": {
            "type": "number"
          },
          "unit_price": {
            "type": "number"
          },
          "line_total": {
            "type": "number"
          },
          "promised_date": {
            "type": "string",
            "description": "Ship or delivery date for the line, ISO 8601, empty if none"
          }
        },
        "required": [
          "sku",
          "quantity",
          "unit_price"
        ]
      }
    },
    "notes": {
      "type": "string",
      "description": "Anything the vendor flags: backorders, substitutions, partial shipments, price changes"
    },
    "extraction_confidence": {
      "type": "number",
      "description": "Your confidence from 0 to 1 that every field above is read correctly from the text"
    }
  },
  "required": [
    "po_number",
    "vendor_name",
    "document_type",
    "currency",
    "total_amount",
    "line_items",
    "extraction_confidence"
  ]
}

