={{ (() => {
  const l = $json;
  if (l.sku === undefined && l.line_no === undefined) return { empty: true };
  const num = v => { const n = typeof v === 'number' ? v : parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : null; };
  const key = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const poLines = $('ValidationInput').first().json.po?.lines || [];
  const m = poLines.find(p => key(p.sku) === key(l.sku)) || poLines.find(p => Number(p.line_no) === Number(l.line_no)) || null;
  const qty = num(l.quantity), price = num(l.unit_price);
  const poQty = m ? num(m.quantity) : null, poPrice = m ? num(m.unit_price) : null;
  const drift = price !== null && poPrice ? Math.round(Math.abs(price - poPrice) / Math.abs(poPrice) * 1000) / 10 : (price !== null && poPrice === 0 ? 100 : 0);
  return {
    sku: l.sku ?? null, line_no: l.line_no ?? null, description: l.description ?? null,
    quantity: qty, unit_price: price, line_total: num(l.line_total) ?? (qty ?? 0) * (price ?? 0),
    matched: !!m, po_line_no: m?.line_no ?? null, po_sku: m?.sku ?? null,
    po_quantity: poQty, po_unit_price: poPrice,
    qty_over: qty !== null && poQty !== null && qty > poQty,
    price_drift_pct: drift,
  };
})() }}

={{ (() => {
  const v = $('ValidationInput').first().json;
  const verdicts = $json;
  const table = $('CollectRules').first().json.rules;
  const setting = (id, fallback) => { const r = table.find(r => r.rule_id === id); return r && r.threshold !== null && r.threshold !== undefined ? Number(r.threshold) : fallback; };
  const rules = table
    .filter(r => r.kind === 'rule' && r.enabled !== false && ('pass_' + r.rule_id) in verdicts)
    .sort((a, b) => (a.rule_id < b.rule_id ? -1 : 1))
    .map(r => ({ id: r.rule_id, name: r.name, pass: verdicts['pass_' + r.rule_id] === true, detail: verdicts['detail_' + r.rule_id] ?? '', weight: Number(r.weight) || 0, hard: r.hard === true }));
  const wTotal = rules.reduce((s, r) => s + r.weight, 0);
  const wPass = rules.filter(r => r.pass).reduce((s, r) => s + r.weight, 0);
  const rulesScore = wTotal ? wPass / wTotal : 0;
  const autoThreshold = setting('AUTO_THRESHOLD', 0.9), aiWeight = setting('AI_WEIGHT', 0.3);
  const score = Math.round(((1 - aiWeight) * rulesScore + aiWeight * v.ai_confidence) * 1000) / 1000;
  const hardFail = rules.some(r => r.hard && !r.pass);
  const decision = (!hardFail && score >= autoThreshold) ? 'auto' : 'review';
  return {
    email: v.email, extracted: v.extracted, po: v.po,
    rule_results: rules, rules_score: Math.round(rulesScore * 1000) / 1000,
    ai_confidence: v.ai_confidence, score, threshold: autoThreshold, hard_fail: hardFail,
    decision, status: decision === 'auto' ? 'auto_approved' : 'pending_review',
    failed_rules: rules.filter(r => !r.pass).map(r => r.id + ' ' + r.name + ': ' + r.detail),
  };
})() }}

parameters.html:
={{ (() => {
  const c = $('ComputeDecision').first().json;
  const ex = c.extracted, po = c.po, esc = s => String(s ?? '').replace(/[<>&]/g, m => ({'<':'&lt;','>':'&gt;','&':'&amp;'}[m]));
  const row = (a, b, cls) => `<tr class="${cls||''}"><td>${a}</td><td>${b}</td></tr>`;
  const rules = c.rule_results.map(r => `<tr style="color:${r.pass ? '#1a7f37' : '#b42318'}"><td>${r.id}</td><td>${esc(r.name)}</td><td>${r.pass ? 'pass' : 'FAIL'}${r.hard ? ' (hard)' : ''}</td><td>${esc(r.detail)}</td></tr>`).join('');
  const lines = (ex.line_items || []).map(l => { const m = (po?.lines || []).find(p => String(p.sku).toLowerCase() === String(l.sku||'').toLowerCase()) || {};
    return `<tr><td>${esc(l.sku)}</td><td>${esc(l.quantity)} / ${esc(m.quantity ?? '-')}</td><td>${esc(l.unit_price)} / ${esc(m.unit_price ?? '-')}</td><td>${esc(l.line_total)}</td></tr>`; }).join('');
  const resume = $execution.resumeUrl;
  const base = resume + (resume.includes('?') ? '&' : '?');
  return `<html><body style="font-family:Arial,sans-serif;font-size:13px">
<h2>PO reconciliation needs a decision</h2>
<p><b>${esc(ex.po_number)}</b> from <b>${esc(ex.vendor_name)}</b> (${esc(ex.document_type)}), reconciliation #${$('LogReconciliation').first().json.id}</p>
<p>Score <b>${c.score}</b> against threshold ${c.threshold}. ${c.hard_fail ? 'A hard rule failed, so this cannot post automatically.' : 'Below the auto-post threshold.'}</p>
<p><a href="${base}decision=approve" style="background:#1a7f37;color:#fff;padding:10px 18px;text-decoration:none;border-radius:4px">Approve and post to SAP</a>
&nbsp;&nbsp;<a href="${base}decision=reject" style="background:#b42318;color:#fff;padding:10px 18px;text-decoration:none;border-radius:4px">Reject</a></p>
<h3>Rules</h3><table border="1" cellpadding="4" cellspacing="0"><tr><th>#</th><th>Rule</th><th>Result</th><th>Detail</th></tr>${rules}</table>
<h3>Lines (document / PO)</h3><table border="1" cellpadding="4" cellspacing="0"><tr><th>SKU</th><th>Qty</th><th>Unit price</th><th>Line total</th></tr>${lines || '<tr><td colspan=4>none extracted</td></tr>'}</table>
<h3>Header</h3><table border="1" cellpadding="4" cellspacing="0">${row('Document total', esc(ex.total_amount) + ' ' + esc(ex.currency))}${row('PO total', po ? esc(po.total_amount) + ' ' + esc(po.currency) : 'PO not found')}${row('Vendor reference', esc(ex.vendor_reference))}${row('Document date', esc(ex.document_date))}${row('Sender', esc(c.email.from))}${row('Subject', esc(c.email.subject))}${row('Model notes', esc(ex.notes))}</table>
<p style="color:#666">Execution ${$execution.id}. Links expire with the execution.</p>
</body></html>`;
})() }}

