={{ (() => {
  const h = $json;
  const c = $('ComputeDecision').first().json;
  const ex = c.extracted, po = c.po || {}, poLines = po.lines || [];
  const d = v => String(v ?? '').slice(0, 10).replace(/-/g, '');
  const seg = { SEGMENT: '1' };
  const items = (ex.line_items || []).map((l, i) => {
    const m = poLines.find(p => String(p.sku).toLowerCase() === String(l.sku ?? '').toLowerCase()) || poLines[i] || {};
    const item = {
      attr: seg,
      POSEX: String(m.line_no ?? l.line_no ?? i + 1).padStart(6, '0'),
      MENGE: l.quantity ?? '', MENEE: 'EA', VPREI: l.unit_price ?? '', NETWR: l.line_total ?? '',
      E1EDP19: { attr: seg, QUALF: '002', IDTLF: m.sku ?? l.sku ?? '', KTEXT: l.description ?? m.description ?? '' },
    };
    if (l.promised_date) item.E1EDP20 = { attr: seg, WMENG: l.quantity ?? '', EDATU: d(l.promised_date) };
    return item;
  });
  const idoc = {
    attr: { BEGIN: '1' },
    EDI_DC40: {
      attr: seg, TABNAM: 'EDI_DC40', DOCNUM: h.idoc_number, DIRECT: '2', IDOCTYP: 'ORDERS05', MESTYP: h.message_type,
      SNDPOR: 'N8N_POC', SNDPRT: 'LS', SNDPRN: 'N8N_OM_POC', RCVPOR: 'SAPERP', RCVPRT: 'LS', RCVPRN: 'OM_ERP',
      CREDAT: h.created_date, CRETIM: h.created_time,
    },
    E1EDK01: { attr: seg, CURCY: ex.currency || po.currency || '', BELNR: ex.vendor_reference ?? '' },
    E1EDK02: [
      { attr: seg, QUALF: '001', BELNR: po.po_number ?? '', DATUM: d(po.order_date) },
      { attr: seg, QUALF: '002', BELNR: ex.vendor_reference ?? '', DATUM: d(ex.document_date) },
    ],
    E1EDKA1: { attr: seg, PARVW: 'LF', PARTN: po.vendor_id ?? '', NAME1: po.vendor_name ?? '' },
    E1EDP01: items,
    E1EDS01: { attr: seg, SUMID: '002', SUMME: ex.total_amount ?? '', SUNIT: ex.currency || po.currency || '' },
  };
  return { IDOC: idoc };
})() }}

